mapper.sql:
SELECT * FROM biz01_promo INNER JOIN crd02_data ON crd02_data_id = biz01_card_data_id INNER JOIN sys01_company ON sys01_company_id = biz01_company_id LEFT OUTER JOIN crd01_card ON crd01_card_id = biz01_card_id LEFT OUTER JOIN crd03_trans ON ( crd03_card_id = biz01_card_id AND biz01_provide_date BETWEEN crd03_fr_dt AND COALESCE(crd03_to_dt,'9999-12-31') ) LEFT OUTER JOIN act01_account_code ON (act01_account_code_id = biz01_account_code_id) WHERE biz01_company_id = #{companyId} AND COALESCE(biz01_provide_pur_cd,'%') LIKE #{providePurCode}
AND biz01_std_ym = #{dataYm}
AND biz01_std_ym BETWEEN #{startYm} AND #{closeYm}
AND CASE WHEN #{managerId} = 0 THEN crd03_public_yn = 'true' ELSE ((CASE WHEN sys01_card_real_user_yn = 'true' THEN (CASE WHEN biz01_real_person_id IS NOT NULL THEN biz01_real_person_id ELSE crd03_person_id END) ELSE (CASE WHEN crd03_public_yn = 'true' THEN 0 ELSE crd03_person_id END) END ) = #{managerId}) END

mapper.select:


 ORDER BY biz01_approval_dt, biz01_approval_time, biz01_franchise_nm
 LIMIT #{limit}
OFFSET #{offset}

SELECT count(*)
  FROM biz01_promo
       INNER JOIN crd01_card ON crd01_card_id = biz01_card_id
 WHERE biz01_company_id = #{companyId}
   AND biz01_std_ym = #{dataYm}
   AND COALESCE(biz01_close_yn,'false') = 'true'

SELECT count(*)
  FROM act05_gen_ledger_close
 WHERE act05_company_id = #{companyId}
   AND TO_CHAR(act05_std_date,'YYYY.MM') >= #{dataYm}

mapper.update:
UPDATE biz01_promo
   SET biz01_provide_pur_cd     = #{req.providePurCode}
     , biz01_provide_content_cd = #{req.provideContentCode}
     , biz01_account_code_id    = #{req.accountCodeId}
     , biz01_note               = #{req.note}
     , biz01_tax_type           = #{req.taxType}
     , biz01_real_person_id     = #{req.realPersonId}
 WHERE biz01_promo_id   = #{promoId}
   AND biz01_company_id = #{companyId}

